import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        // valid[i]: the prefix s[0..i-1] has no equal adjacent characters.
        boolean[] valid = new boolean[n + 1];
        valid[0] = true;
        valid[1] = true;
        for (int i = 1; i < n; i++) valid[i + 1] = valid[i] && s.charAt(i) != s.charAt(i - 1);
        // The later the first changed position, the smaller the result.
        for (int i = n - 1; i >= 0; i--) {
            if (!valid[i]) continue;
            for (char c = (char) (s.charAt(i) + 1); c <= 'z'; c++) {
                if (i > 0 && c == s.charAt(i - 1)) continue;
                char[] out = new char[n];
                s.getChars(0, i, out, 0);
                out[i] = c;
                for (int j = i + 1; j < n; j++) out[j] = out[j - 1] != 'a' ? 'a' : 'b';
                System.out.println(new String(out));
                return;
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"io"
	"os"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	n := len(s)
	// valid[i]: the prefix s[0..i-1] has no equal adjacent characters.
	valid := make([]bool, n+1)
	valid[0], valid[1] = true, true
	for i := 1; i < n; i++ {
		valid[i+1] = valid[i] && s[i] != s[i-1]
	}
	// The later the first changed position, the smaller the result.
	for i := n - 1; i >= 0; i-- {
		if !valid[i] {
			continue
		}
		for c := s[i] + 1; c <= 'z'; c++ {
			if i > 0 && c == s[i-1] {
				continue
			}
			out := make([]byte, n, n+1)
			copy(out, s[:i])
			out[i] = c
			for j := i + 1; j < n; j++ {
				if out[j-1] != 'a' {
					out[j] = 'a'
				} else {
					out[j] = 'b'
				}
			}
			os.Stdout.Write(append(out, '\n'))
			return
		}
	}
	os.Stdout.WriteString("-1\n")
}
